seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]==0 and (nx,ny) not in seen:
