   comps.append(comp)
holes=[]
for comp in comps:
 if not any(r in (0,R-1) or c in (0,C-1) for r,c in comp):
  holes.append(comp)
[(len(h), (min(r for r,c in h),max(r for r,c in h),min(c for r,c in h),max(c for r,c in h))) for h in holes]

