   out[r][c]=3
for r in range(R):
 if out[r]!=grid[r]:
  print(f'{r:02d}', ''.join(map(str,grid[r])), '=>',''.join(map(str,out[r])))

diff3=[]
for h in holes:
 for r,c in h:
  n4=any(0<=r+dr<R and 0<=c+dc<C and grid[r+dr][c+dc]==1 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)])
  n8=any(0<=r+dr<R and 0<=c+dc<C and grid[r+dr][c+dc]==1 for dr in [-1,0,1] for dc in [-1,0,1] if (dr,dc)!=(0,0))
  if n8 and not n4: diff3.append((r,c))
diff3

